    15→package org.hyperledger.besu.evm.precompile;
    16→
    17→import static org.hyperledger.besu.evm.internal.Words.clampedAdd;
    18→import static org.hyperledger.besu.evm.internal.Words.clampedMultiply;
    19→import static org.hyperledger.besu.evm.internal.Words.clampedToInt;
    20→import static org.hyperledger.besu.evm.internal.Words.clampedToLong;
    21→
    22→import org.hyperledger.besu.evm.frame.ExceptionalHaltReason;
    23→import org.hyperledger.besu.evm.frame.MessageFrame;
    24→import org.hyperledger.besu.evm.gascalculator.GasCalculator;
    25→import org.hyperledger.besu.nativelib.arithmetic.LibArithmetic;
    26→
    27→import java.math.BigInteger;
    28→import java.util.Optional;
    29→
    30→import com.sun.jna.ptr.IntByReference;
    31→import jakarta.validation.constraints.NotNull;
    32→import org.apache.tuweni.bytes.Bytes;
    33→import org.apache.tuweni.bytes.MutableBytes;
    34→import org.slf4j.Logger;
    35→import org.slf4j.LoggerFactory;
    36→
    37→/** The Big integer modular exponentiation precompiled contract defined in EIP-198. */
    38→public class BigIntegerModularExponentiationPrecompiledContract
    39→    extends AbstractPrecompiledContract {
    40→
    41→  private static final Logger LOG =
    42→      LoggerFactory.getLogger(BigIntegerModularExponentiationPrecompiledContract.class);
    43→
    44→  /** Use native Arithmetic libraries. */
    45→  private static boolean useNative;
    46→
    47→  /** The constant BASE_OFFSET. */
    48→  public static final int BASE_OFFSET = 96;
    49→
    50→  private static final int PARAMETER_LENGTH = 32;
    51→  private static final int BASE_LENGTH_OFFSET = 0;
    52→  private static final int EXPONENT_LENGTH_OFFSET = 32;
    53→  private static final int MODULUS_LENGTH_OFFSET = 64;
    54→
    55→  private final long upperBound;
    56→
    57→  /**
    58→   * Instantiates a new BigInteger modular exponentiation precompiled contract.
    59→   *
    60→   * @param gasCalculator the gas calculator
    61→   */
    62→  BigIntegerModularExponentiationPrecompiledContract(
    63→      final GasCalculator gasCalculator, final long upperBound) {
    64→    super("MODEXP", gasCalculator);
    65→    this.upperBound = upperBound;
    66→  }
    67→
    68→  /** Disable native Arithmetic libraries. */
    69→  public static void disableNative() {
    70→    useNative = false;
    71→  }
    72→
    73→  /**
    74→   * Attempt to enable the native library for ModExp
    75→   *
    76→   * @return true if the native library was enabled.
    77→   */
    78→  public static boolean maybeEnableNative() {
    79→    try {
    80→      useNative = LibArithmetic.ENABLED;
    81→    } catch (UnsatisfiedLinkError | NoClassDefFoundError ule) {
    82→      LOG.info("modexp native precompile not available: {}", ule.getMessage());
    83→      useNative = false;
    84→    }
    85→    return useNative;
    86→  }
    87→
    88→  /**
    89→   * Check if native Arithmetic libraries are enabled.
    90→   *
    91→   * @return the boolean
    92→   */
    93→  public static boolean isNative() {
    94→    return useNative;
    95→  }
    96→
    97→  @Override
    98→  public long gasRequirement(final Bytes input) {
    99→    return gasCalculator().modExpGasCost(input);
   100→  }
   101→
   102→  @NotNull
   103→  @Override
   104→  public PrecompileContractResult computePrecompile(
   105→      final Bytes input, @NotNull final MessageFrame messageFrame) {
   106→    // https://eips.ethereum.org/EIPS/eip-7823
   107→    // We introduce an upper bound to the inputs of the precompile,
   108→    // each of the length inputs (length_of_BASE, length_of_EXPONENT and length_of_MODULUS)
   109→    // MUST be less than or equal to 1024 bytes
   110→    final long length_of_BASE = baseLength(input);
   111→    final long length_of_EXPONENT = exponentLength(input);
   112→    final long length_of_MODULUS = modulusLength(input);
   113→    if (length_of_BASE > upperBound
   114→        || length_of_EXPONENT > upperBound
   115→        || length_of_MODULUS > upperBound) {
   116→      return PrecompileContractResult.halt(
   117→          null, Optional.of(ExceptionalHaltReason.PRECOMPILE_ERROR));
   118→    }
   119→
   120→    // OPTIMIZATION: overwrite native setting for this case
   121→    if (LibArithmetic.ENABLED) {
   122→      final int baseOffset = clampedToInt(BASE_OFFSET);
   123→      final int baseLength = clampedToInt(length_of_BASE);
   124→      final int modulusLength = clampedToInt(length_of_MODULUS);
   125→      if ((extractLastByte(input, baseOffset, baseLength) & 1) != 1) {
   126→        return computeNative(input, modulusLength);
   127→      }
   128→    }
   129→
   130→    if (useNative) {
   131→      final int modulusLength = clampedToInt(length_of_MODULUS);
   132→      return computeNative(input, modulusLength);
   133→    } else {
   134→      final int baseLength = clampedToInt(length_of_BASE);
   135→      final int exponentLength = clampedToInt(length_of_EXPONENT);
   136→      final int modulusLength = clampedToInt(length_of_MODULUS);
   137→      return computeDefault(input, baseLength, exponentLength, modulusLength);
   138→    }
   139→  }
   140→
   141→  @NotNull
   142→  private PrecompileContractResult computeDefault(
   143→      final Bytes input, final int baseLength, final int exponentLength, final int modulusLength) {
   144→    // If baseLength and modulusLength are zero
   145→    // we could have a massively overflowing exp because it wouldn't have been filtered out at the
   146→    // gas cost phase
   147→    if ((baseLength == 0) && (modulusLength == 0)) {
   148→      return PrecompileContractResult.success(Bytes.EMPTY);
   149→    }
   150→    final int exponentOffset = BASE_OFFSET + baseLength;
   151→    final int modulusOffset = exponentOffset + exponentLength;
   152→    final BigInteger base = extractParameter(input, BASE_OFFSET, baseLength);
   153→    final BigInteger exp = extractParameter(input, exponentOffset, exponentLength);
   154→    final BigInteger mod = extractParameter(input, modulusOffset, modulusLength);
   155→
   156→    final Bytes modExp;
   157→    // Result must be the length of the modulus.
   158→    final MutableBytes result = MutableBytes.create(modulusLength);
   159→    if (mod.compareTo(BigInteger.ZERO) == 0) {
   160→      modExp = MutableBytes.EMPTY;
   161→    } else {
   162→      // BigInteger zero-pads positive values whose most significant bit is a 1 if
   163→      // the padding was not there.
   164→      modExp = Bytes.wrap(base.modPow(exp, mod).toByteArray()).trimLeadingZeros();
   165→    }
   166→
   167→    modExp.copyTo(result, result.size() - modExp.size());
   168→    return PrecompileContractResult.success(result);
   169→  }
   170→
   171→  /**
   172→   * Equation to estimate the multiplication complexity.
   173→   *
   174→   * @param x the x
   175→   * @return the long
   176→   */
   177→  public static long multiplicationComplexity(final long x) {
   178→    if (x <= 64) {
   179→      return square(x);
   180→    } else if (x <= 1024) {
   181→      return clampedAdd((square(x) / 4), clampedMultiply(x, 96)) - 3072;
   182→    } else {
   183→      return clampedAdd((square(x) / 16), clampedMultiply(480, x)) - 199680;
   184→    }
   185→  }
   186→
   187→  /**
   188→   * Base length.
   189→   *
   190→   * @param input the input
   191→   * @return the long
   192→   */
   193→  public static long baseLength(final Bytes input) {
   194→    return extractParameterLong(input, BASE_LENGTH_OFFSET, PARAMETER_LENGTH);
   195→  }
   196→
   197→  /**
   198→   * Exponent length.
   199→   *
   200→   * @param input the input
   201→   * @return the long
   202→   */
   203→  public static long exponentLength(final Bytes input) {
   204→    return extractParameterLong(input, EXPONENT_LENGTH_OFFSET, PARAMETER_LENGTH);
   205→  }
   206→
   207→  /**
   208→   * Modulus length.
   209→   *
   210→   * @param input the input
   211→   * @return the long
   212→   */
   213→  public static long modulusLength(final Bytes input) {
   214→    return extractParameterLong(input, MODULUS_LENGTH_OFFSET, PARAMETER_LENGTH);
   215→  }
   216→
   217→  /**
   218→   * Extract parameter.
   219→   *
   220→   * @param input the input
   221→   * @param offset the offset
   222→   * @param length the length
   223→   * @return the big integer
   224→   */
   225→  public static BigInteger extractParameter(final Bytes input, final int offset, final int length) {
   226→    if (offset >= input.size() || length == 0) {
   227→      return BigInteger.ZERO;
   228→    } else if (offset + length < input.size()) {
   229→      return new BigInteger(1, input.slice(offset, length).toArray());
   230→    } else {
   231→      byte[] raw = new byte[length];
   232→      Bytes partial = input.slice(offset);
   233→      System.arraycopy(partial.toArray(), 0, raw, 0, partial.size());
   234→      return new BigInteger(1, raw);
   235→    }
   236→  }
   237→
   238→  private static byte extractLastByte(final Bytes input, final int offset, final int length) {
   239→    if (offset >= input.size() || length == 0) {
   240→      return 0;
   241→    } else if (offset + length <= input.size()) {
   242→      return input.get(offset + length - 1);
   243→    }
   244→    Bytes partial = input.slice(offset);
   245→    return partial.get(partial.size() - 1);
   246→  }
   247→
   248→  /**
   249→   * Extract parameter.
   250→   *
   251→   * @param input the input
   252→   * @param offset the offset
   253→   * @param length the length
   254→   * @return the long
   255→   */
   256→  public static long extractParameterLong(final Bytes input, final int offset, final int length) {
   257→    if (offset >= input.size() || length == 0) {
   258→      return 0;
   259→    }
   260→    Bytes num;
   261→    if (offset + length <= input.size()) {
   262→      num = input.slice(offset, length).trimLeadingZeros();
   263→    } else {
   264→      // Ethereum's memory is always infinitely full of zeros, but we don't store those zeros, just
   265→      // what we write.  If we are asked for a range that is outside the written memory create a
   266→      // result of the correct size (defaults to zeros) and copy the memory we do have into there.
   267→      MutableBytes mut = MutableBytes.create(length);
   268→      input.slice(offset).copyTo(mut, 0);
   269→      num = mut.trimLeadingZeros();
   270→    }
   271→    return clampedToLong(num);
   272→  }
   273→
   274→  private static long square(final long n) {
   275→    return clampedMultiply(n, n);
   276→  }
   277→
   278→  private PrecompileContractResult computeNative(
   279→      final @NotNull Bytes input, final int modulusLength) {
   280→    final IntByReference o_len = new IntByReference(modulusLength);
   281→
   282→    final byte[] result = new byte[modulusLength];
   283→    final int errorNo =
   284→        LibArithmetic.modexp_precompiled(input.toArrayUnsafe(), input.size(), result, o_len);
   285→    if (errorNo == 0) {
   286→      return PrecompileContractResult.success(Bytes.wrap(result, 0, o_len.getValue()));
   287→    } else {
   288→      LOG.trace("Error executing precompiled contract {}: {}", getName(), errorNo);
   289→      return PrecompileContractResult.halt(
   290→          null, Optional.of(ExceptionalHaltReason.PRECOMPILE_ERROR));
   291→    }
   292→  }
   293→}
