    15→package org.hyperledger.besu.evm.precompile;
    16→
    17→import static org.assertj.core.api.Assertions.assertThat;
    18→import static org.hyperledger.besu.evm.precompile.BigIntegerModularExponentiationPrecompiledContract.disableNative;
    19→import static org.hyperledger.besu.evm.precompile.BigIntegerModularExponentiationPrecompiledContract.maybeEnableNative;
    20→
    21→import org.hyperledger.besu.datatypes.Address;
    22→import org.hyperledger.besu.evm.EvmSpecVersion;
    23→import org.hyperledger.besu.evm.fluent.EvmSpec;
    24→import org.hyperledger.besu.evm.frame.ExceptionalHaltReason;
