    16→
    17→import static org.hyperledger.besu.evm.internal.Words.clampedAdd;
    18→import static org.hyperledger.besu.evm.internal.Words.clampedMultiply;
    19→import static org.hyperledger.besu.evm.internal.Words.clampedToInt;
    20→
    21→import org.hyperledger.besu.evm.precompile.BigIntegerModularExponentiationPrecompiledContract;
    22→
    23→import java.math.BigInteger;
    24→
    25→import org.apache.tuweni.bytes.Bytes;
    26→
    27→/** The Byzantium gas calculator. */
    28→public class ByzantiumGasCalculator extends SpuriousDragonGasCalculator {
    29→  /** word size */
    30→  protected static final int WORD_SIZE = 32;
    31→
    32→  private static final int GQUADDIVISOR = 20;
    33→  private static final int BITS_IN_BYTE = 8;
    34→
    35→  /** The constant MAX_FIRST_EXPONENT_BYTES. */
    36→  public static final int MAX_FIRST_EXPONENT_BYTES = 32;
    37→
    38→  /** Default constructor. */
    39→  public ByzantiumGasCalculator() {}
    40→
    41→  @Override
    42→  public long modExpGasCost(final Bytes input) {
    43→    final long baseLength = BigIntegerModularExponentiationPrecompiledContract.baseLength(input);
    44→    final long exponentLength =
    45→        BigIntegerModularExponentiationPrecompiledContract.exponentLength(input);
    46→    final long modulusLength =
    47→        BigIntegerModularExponentiationPrecompiledContract.modulusLength(input);
    48→    final long exponentOffset =
    49→        clampedAdd(BigIntegerModularExponentiationPrecompiledContract.BASE_OFFSET, baseLength);
    50→    final long firstExponentBytesCap = Math.min(exponentLength, MAX_FIRST_EXPONENT_BYTES);
    51→    final BigInteger firstExpBytes =
    52→        BigIntegerModularExponentiationPrecompiledContract.extractParameter(
    53→            input, clampedToInt(exponentOffset), clampedToInt(firstExponentBytesCap));
    54→    final long adjustedExponentLength = adjustedExponentLength(exponentLength, firstExpBytes);
    55→    final long multiplicationComplexity =
    56→        BigIntegerModularExponentiationPrecompiledContract.multiplicationComplexity(
    57→            Math.max(baseLength, modulusLength));
    58→    long numerator = clampedMultiply(multiplicationComplexity, Math.max(adjustedExponentLength, 1));
    59→    return (numerator == Long.MAX_VALUE) ? Long.MAX_VALUE : numerator / GQUADDIVISOR;
    60→  }
    61→
    62→  /**
    63→   * Adjusted exponent length.
    64→   *
    65→   * @param exponentLength the exponent length
    66→   * @param firstExpBytes the first exp bytes
    67→   * @return the long
    68→   */
    69→  public static long adjustedExponentLength(
    70→      final long exponentLength, final BigInteger firstExpBytes) {
    71→    final int bitLength = bitLength(firstExpBytes);
    72→    if (exponentLength < WORD_SIZE) {
    73→      return bitLength;
    74→    } else {
    75→      return clampedAdd(clampedMultiply(BITS_IN_BYTE, (exponentLength - WORD_SIZE)), bitLength);
    76→    }
    77→  }
    78→
    79→  /**
    80→   * Compute the length in bits of the given integer
    81→   *
    82→   * @param n big integer for which to calculate length
    83→   * @return bit length
    84→   */
    85→  protected static int bitLength(final BigInteger n) {
    86→    return n.compareTo(BigInteger.ZERO) == 0 ? 0 : (n.bitLength() - 1);
    87→  }
    88→}
