    35→/** The Berlin gas calculator. */
    36→public class BerlinGasCalculator extends IstanbulGasCalculator {
    37→
    38→  // new constants for EIP-2929
    39→  private static final long COLD_SLOAD_COST = 2100L;
    40→  private static final long COLD_ACCOUNT_ACCESS_COST = 2600L;
    41→
    42→  /** Warm storage read, defined in EIP-2929 */
    43→  protected static final long WARM_STORAGE_READ_COST = 100L;
    44→
    45→  private static final long ACCESS_LIST_ADDRESS_COST = 2400L;
    46→
    47→  /** The constant ACCESS_LIST_STORAGE_COST. */
    48→  protected static final long ACCESS_LIST_STORAGE_COST = 1900L;
    49→
    50→  // redefinitions for EIP-2929
    51→  private static final long SLOAD_GAS = WARM_STORAGE_READ_COST;
    52→
    53→  /** The constant SSTORE_RESET_GAS. */
    54→  protected static final long SSTORE_RESET_GAS = 5000L - COLD_SLOAD_COST;
    55→
    56→  // unchanged from Istanbul
    57→  private static final long SSTORE_SET_GAS = 20_000L;
    58→  private static final long SSTORE_CLEARS_SCHEDULE = 15_000L;
    59→
    60→  /** The constant SSTORE_SET_GAS_LESS_SLOAD_GAS. */
    61→  protected static final long SSTORE_SET_GAS_LESS_SLOAD_GAS = SSTORE_SET_GAS - SLOAD_GAS;
    62→
    63→  /** The constant SSTORE_RESET_GAS_LESS_SLOAD_GAS. */
    64→  protected static final long SSTORE_RESET_GAS_LESS_SLOAD_GAS = SSTORE_RESET_GAS - SLOAD_GAS;
    65→
    66→  private static final long NEGATIVE_SSTORE_CLEARS_SCHEDULE = -SSTORE_CLEARS_SCHEDULE;
    67→
    68→  // unchanged from Frontier
    69→  private static final long COPY_WORD_GAS_COST = 3L;
    70→
    71→  /** configured maximum valid precompile address for this fork/gas calculator */
    72→  protected final int maxPrecompile;
    73→
    74→  /**
    75→   * Instantiates a new Berlin gas calculator.
    76→   *
    77→   * @param maxPrecompile the max precompile
    78→   */
    79→  protected BerlinGasCalculator(final int maxPrecompile) {
    80→    this.maxPrecompile = maxPrecompile;
    81→  }
    82→
    83→  /** Instantiates a new Berlin gas calculator. */
    84→  public BerlinGasCalculator() {
    85→    this(BLAKE2B_F_COMPRESSION.toArrayUnsafe()[19]);
    86→  }
    87→
    88→  @Override
    89→  public long accessListGasCost(final int addresses, final int storageSlots) {
    90→    return ACCESS_LIST_ADDRESS_COST * addresses + (ACCESS_LIST_STORAGE_COST * storageSlots);
    91→  }
    92→
    93→  @Override
    94→  public boolean isPrecompile(final Address address) {
    95→    final byte[] addressBytes = address.toArrayUnsafe();
    96→    for (int i = 0; i < 19; i++) {
    97→      if (addressBytes[i] != 0) {
    98→        return false;
    99→      }
   100→    }
   101→    final int lastByte = Byte.toUnsignedInt(addressBytes[19]);
   102→    return lastByte <= maxPrecompile && lastByte != 0;
   103→  }
   104→
   105→  // new costs
   106→  @Override
   107→  public long getColdSloadCost() {
   108→    return COLD_SLOAD_COST;
   109→  }
   110→
   111→  @Override
   112→  public long getColdAccountAccessCost() {
   113→    return COLD_ACCOUNT_ACCESS_COST;
   114→  }
   115→
   116→  @Override
   117→  public long getWarmStorageReadCost() {
   118→    return WARM_STORAGE_READ_COST;
   119→  }
   120→
   121→  // Zeroed out old costs
   122→  @Override
   123→  public long getBalanceOperationGasCost() {
   124→    return 0L;
   125→  }
   126→
   127→  @Override
   128→  public long callOperationBaseGasCost() {
   129→    return 0L;
   130→  }
   131→
   132→  @Override
   133→  public long extCodeHashOperationGasCost() {
   134→    return 0L;
   135→  }
   136→
   137→  @Override
   138→  public long getExtCodeSizeOperationGasCost() {
   139→    return 0L;
   140→  }
   141→
   142→  @Override
   143→  public long getSloadOperationGasCost() {
   144→    return 0L;
   145→  }
   146→
   147→  // Redefined costs from EIP-2929
   148→  @Override
   149→  public long callOperationGasCost(
   150→      final MessageFrame frame,
   151→      final long stipend,
   152→      final long inputDataOffset,
   153→      final long inputDataLength,
   154→      final long outputDataOffset,
   155→      final long outputDataLength,
   156→      final Wei transferValue,
   157→      final Account recipient,
   158→      final Address to,
   159→      final boolean accountIsWarm) {
   160→    final long baseCost =
   161→        super.callOperationGasCost(
   162→            frame,
   163→            stipend,
   164→            inputDataOffset,
   165→            inputDataLength,
   166→            outputDataOffset,
   167→            outputDataLength,
   168→            transferValue,
   169→            recipient,
   170→            to,
   171→            true); // we want the "warmed price" as we will charge for warming ourselves
   172→    return clampedAdd(
   173→        baseCost, accountIsWarm ? getWarmStorageReadCost() : getColdAccountAccessCost());
   174→  }
   175→
   176→  // defined in Frontier, but re-implemented with no base cost.
   177→  @Override
   178→  public long extCodeCopyOperationGasCost(
   179→      final MessageFrame frame, final long offset, final long length) {
   180→    return copyWordsToMemoryGasCost(frame, 0L, COPY_WORD_GAS_COST, offset, length);
   181→  }
   182→
   183→  // defined in Istanbul, but re-implemented with new constants
   184→  @Override
   185→  // As per https://eips.ethereum.org/EIPS/eip-2200
   186→  public long calculateStorageCost(
   187→      final UInt256 newValue,
   188→      final Supplier<UInt256> currentValue,
   189→      final Supplier<UInt256> originalValue) {
   190→
   191→    final UInt256 localCurrentValue = currentValue.get();
   192→    if (localCurrentValue.equals(newValue)) {
   193→      return SLOAD_GAS;
   194→    } else {
   195→      final UInt256 localOriginalValue = originalValue.get();
   196→      if (localOriginalValue.equals(localCurrentValue)) {
   197→        return localOriginalValue.isZero() ? SSTORE_SET_GAS : SSTORE_RESET_GAS;
   198→      } else {
   199→        return SLOAD_GAS;
   200→      }
   201→    }
   202→  }
   203→
   204→  // defined in Istanbul, but re-implemented with new constants
   205→  @Override
   206→  // As per https://eips.ethereum.org/EIPS/eip-2200
   207→  public long calculateStorageRefundAmount(
   208→      final UInt256 newValue,
   209→      final Supplier<UInt256> currentValue,
   210→      final Supplier<UInt256> originalValue) {
   211→
   212→    final UInt256 localCurrentValue = currentValue.get();
   213→    if (localCurrentValue.equals(newValue)) {
   214→      return 0L;
   215→    } else {
   216→      final UInt256 localOriginalValue = originalValue.get();
   217→      if (localOriginalValue.equals(localCurrentValue)) {
   218→        if (localOriginalValue.isZero()) {
   219→          return 0L;
   220→        } else if (newValue.isZero()) {
   221→          return SSTORE_CLEARS_SCHEDULE;
   222→        } else {
   223→          return 0L;
   224→        }
   225→      } else {
   226→        long refund = 0L;
   227→        if (!localOriginalValue.isZero()) {
   228→          if (localCurrentValue.isZero()) {
   229→            refund = NEGATIVE_SSTORE_CLEARS_SCHEDULE;
   230→          } else if (newValue.isZero()) {
   231→            refund = SSTORE_CLEARS_SCHEDULE;
   232→          }
   233→        }
   234→
   235→        if (localOriginalValue.equals(newValue)) {
   236→          refund =
   237→              refund
   238→                  + (localOriginalValue.isZero()
   239→                      ? SSTORE_SET_GAS_LESS_SLOAD_GAS
   240→                      : SSTORE_RESET_GAS_LESS_SLOAD_GAS);
   241→        }
   242→        return refund;
   243→      }
   244→    }
   245→  }
   246→
   247→  @Override
   248→  public long modExpGasCost(final Bytes input) {
   249→    final long baseLength = BigIntegerModularExponentiationPrecompiledContract.baseLength(input);
   250→    final long exponentLength =
   251→        BigIntegerModularExponentiationPrecompiledContract.exponentLength(input);
   252→    final long modulusLength =
   253→        BigIntegerModularExponentiationPrecompiledContract.modulusLength(input);
   254→    final long exponentOffset =
   255→        clampedAdd(BigIntegerModularExponentiationPrecompiledContract.BASE_OFFSET, baseLength);
   256→
   257→    long multiplicationComplexity = (Math.max(modulusLength, baseLength) + 7L) / 8L;
   258→    multiplicationComplexity =
   259→        Words.clampedMultiply(multiplicationComplexity, multiplicationComplexity);
   260→
   261→    if (multiplicationComplexity == 0) {
   262→      return 200;
   263→    } else if (multiplicationComplexity > 0) {
   264→      long maxExponentLength = Long.MAX_VALUE / multiplicationComplexity * 3 / 8;
   265→      if (exponentLength > maxExponentLength) {
   266→        return Long.MAX_VALUE;
   267→      }
   268→    }
   269→
   270→    final long firstExponentBytesCap =
   271→        Math.min(exponentLength, ByzantiumGasCalculator.MAX_FIRST_EXPONENT_BYTES);
   272→    final BigInteger firstExpBytes =
   273→        BigIntegerModularExponentiationPrecompiledContract.extractParameter(
   274→            input, clampedToInt(exponentOffset), clampedToInt(firstExponentBytesCap));
   275→    final long adjustedExponentLength = adjustedExponentLength(exponentLength, firstExpBytes);
   276→
   277→    long gasRequirement =
   278→        clampedMultiply(multiplicationComplexity, Math.max(adjustedExponentLength, 1L));
   279→    if (gasRequirement != Long.MAX_VALUE) {
   280→      gasRequirement /= 3;
   281→    }
   282→
   283→    return Math.max(gasRequirement, 200L);
   284→  }
   285→}
