    31→public class DepositRequestProcessor implements RequestProcessor {
    32→  private static final LogTopic DEPOSIT_EVENT_TOPIC =
    33→      LogTopic.wrap(
    34→          Bytes.fromHexString(
    35→              "0x649bbc62d0e31342afea4e5cd82d4049e7e1ee912fc0889aa790803be39038c5"));
    36→
    37→  private final Optional<Address> depositContractAddress;
    38→
    39→  public DepositRequestProcessor(final Address depositContractAddress) {
    40→    this.depositContractAddress = Optional.ofNullable(depositContractAddress);
    41→  }
    42→
    43→  @Override
    44→  public Request process(final RequestProcessingContext context) {
    45→    if (depositContractAddress.isEmpty()) {
    46→      return new Request(RequestType.DEPOSIT, Bytes.EMPTY);
    47→    }
    48→    Optional<Bytes> depositRequests = getDepositRequestData(context.transactionReceipts());
    49→    return new Request(RequestType.DEPOSIT, depositRequests.orElse(Bytes.EMPTY));
    50→  }
    51→
    52→  @VisibleForTesting
    53→  Optional<Bytes> getDepositRequestData(final List<TransactionReceipt> transactionReceipts) {
    54→    return depositContractAddress.flatMap(
    55→        address ->
    56→            transactionReceipts.stream()
    57→                .flatMap(receipt -> receipt.getLogsList().stream())
    58→                .filter(log -> isDepositEvent(address, log))
    59→                .map(DepositLogDecoder::decodeFromLog)
    60→                .reduce(Bytes::concatenate));
    61→  }
    62→
    63→  private boolean isDepositEvent(final Address depositContractAddress, final Log log) {
    64→    return depositContractAddress.equals(log.getLogger())
    65→        && !log.getTopics().isEmpty()
    66→        && log.getTopics().getFirst().equals(DEPOSIT_EVENT_TOPIC);
    67→  }
    68→
    69→  @Override
    70→  public Optional<String> getContractName() {
    71→    return Optional.of("DEPOSIT_CONTRACT_ADDRESS");
    72→  }
    73→
    74→  @Override
    75→  public Optional<Address> getContractAddress() {
    76→    return depositContractAddress;
    77→  }
    78→}
