    47→  }
    48→
    49→  /**
    50→   * At the start of executing the transaction, after incrementing the sender’s nonce, for each
    51→   * authorization we do the following:
    52→   *
    53→   * <ol>
    54→   *   <li>Verify the chain id is either 0 or the chain's current ID.
    55→   *   <li>`authority = ecrecover(keccak(MAGIC || rlp([chain_id, address, nonce])), y_parity, r, s]`
    56→   *   <li>Add `authority` to `accessed_addresses` (as defined in [EIP-2929](./eip-2929.md).)
    57→   *   <li>Verify the code of `authority` is either empty or already delegated.
    58→   *   <li>Verify the nonce of `authority` is equal to `nonce`.
    59→   *   <li>Add `PER_EMPTY_ACCOUNT_COST - PER_AUTH_BASE_COST` gas to the global refund counter if
    60→   *       `authority` exists in the trie.
    61→   *   <li>Set the code of `authority` to be `0xef0100 || address`. This is a delegation
    62→   *       designation.
    63→   *   <li>Increase the nonce of `authority` by one.
    64→   * </ol>
    65→   *
    66→   * @param worldUpdater The world state updater which is aware of code delegation.
    67→   * @param transaction The transaction being processed.
    68→   * @return The result of the code delegation processing.
    69→   */
    70→  public CodeDelegationResult process(
    71→      final WorldUpdater worldUpdater,
    72→      final Transaction transaction,
    73→      final Optional<TransactionAccessList> eip7928AccessList) {
    74→    final CodeDelegationResult result = new CodeDelegationResult();
    75→
    76→    transaction
    77→        .getCodeDelegationList()
    78→        .get()
    79→        .forEach(
    80→            codeDelegation ->
    81→                processCodeDelegation(worldUpdater, codeDelegation, result, eip7928AccessList));
    82→
    83→    return result;
    84→  }
    85→
    86→  private void processCodeDelegation(
    87→      final WorldUpdater worldUpdater,
    88→      final CodeDelegation codeDelegation,
    89→      final CodeDelegationResult result,
    90→      final Optional<TransactionAccessList> eip7928AccessList) {
    91→    LOG.trace("Processing code delegation: {}", codeDelegation);
    92→
    93→    if (maybeChainId.isPresent()
    94→        && !codeDelegation.chainId().equals(BigInteger.ZERO)
    95→        && !maybeChainId.get().equals(codeDelegation.chainId())) {
    96→      LOG.trace(
    97→          "Invalid chain id for code delegation. Expected: {}, Actual: {}",
    98→          maybeChainId.get(),
    99→          codeDelegation.chainId());
   100→      return;
   101→    }
   102→
   103→    if (codeDelegation.nonce() == MAX_NONCE) {
   104→      LOG.trace("Nonce of code delegation must be less than 2^64-1");
   105→      return;
   106→    }
   107→
   108→    if (codeDelegation.signature().getS().compareTo(halfCurveOrder) > 0) {
   109→      LOG.trace(
   110→          "Invalid signature for code delegation. S value must be less or equal than the half curve order.");
   111→      return;
   112→    }
   113→
   114→    final Optional<Address> authorizer = codeDelegation.authorizer();
   115→    if (authorizer.isEmpty()) {
   116→      LOG.trace("Invalid signature for code delegation");
   117→      return;
   118→    }
   119→
   120→    LOG.trace("Set code delegation for authority: {}", authorizer.get());
   121→
   122→    final Optional<MutableAccount> maybeAuthorityAccount =
   123→        Optional.ofNullable(worldUpdater.getAccount(authorizer.get()));
   124→    eip7928AccessList.ifPresent(t -> t.addAccount(authorizer.get()));
   125→    result.addAccessedDelegatorAddress(authorizer.get());
   126→
   127→    MutableAccount authority;
   128→    boolean authorityDoesAlreadyExist = false;
   129→    if (maybeAuthorityAccount.isEmpty()) {
   130→      // only create an account if nonce is valid
   131→      if (codeDelegation.nonce() != 0) {
   132→        return;
   133→      }
   134→      authority = worldUpdater.createAccount(authorizer.get());
   135→      eip7928AccessList.ifPresent(t -> t.addAccount(authority.getAddress()));
   136→    } else {
   137→      authority = maybeAuthorityAccount.get();
   138→      eip7928AccessList.ifPresent(t -> t.addAccount(authority.getAddress()));
   139→
   140→      if (!codeDelegationService.canSetCodeDelegation(authority)) {
   141→        return;
   142→      }
   143→
   144→      authorityDoesAlreadyExist = true;
   145→    }
   146→
   147→    if (codeDelegation.nonce() != authority.getNonce()) {
   148→      LOG.trace(
   149→          "Invalid nonce for code delegation. Expected: {}, Actual: {}",
   150→          authority.getNonce(),
   151→          codeDelegation.nonce());
   152→      return;
   153→    }
   154→
   155→    if (authorityDoesAlreadyExist) {
   156→      result.incrementAlreadyExistingDelegators();
   157→    }
   158→
   159→    codeDelegationService.processCodeDelegation(authority, codeDelegation.address());
   160→    authority.incrementNonce();
   161→  }
   162→}
