    15→package org.hyperledger.besu.evm.operation;
    16→
    17→import static org.apache.tuweni.bytes.Bytes32.leftPad;
    18→import static org.hyperledger.besu.evm.internal.Words.clampedToLong;
    19→
    20→import org.hyperledger.besu.datatypes.Address;
    21→import org.hyperledger.besu.evm.EVM;
    22→import org.hyperledger.besu.evm.frame.ExceptionalHaltReason;
    23→import org.hyperledger.besu.evm.frame.MessageFrame;
    24→import org.hyperledger.besu.evm.gascalculator.GasCalculator;
    25→import org.hyperledger.besu.evm.log.Log;
    26→import org.hyperledger.besu.evm.log.LogTopic;
    27→
    28→import com.google.common.collect.ImmutableList;
    29→import org.apache.tuweni.bytes.Bytes;
    30→
    31→/** The Log operation. */
    32→public class LogOperation extends AbstractOperation {
    33→
    34→  private final int numTopics;
    35→
    36→  /**
    37→   * Instantiates a new Log operation.
    38→   *
    39→   * @param numTopics the num topics
    40→   * @param gasCalculator the gas calculator
    41→   */
    42→  public LogOperation(final int numTopics, final GasCalculator gasCalculator) {
    43→    super(0xA0 + numTopics, "LOG" + numTopics, numTopics + 2, 0, gasCalculator);
    44→    this.numTopics = numTopics;
    45→  }
    46→
    47→  @Override
    48→  public OperationResult execute(final MessageFrame frame, final EVM evm) {
    49→    final long dataLocation = clampedToLong(frame.popStackItem());
    50→    final long numBytes = clampedToLong(frame.popStackItem());
    51→
    52→    if (frame.isStatic()) {
    53→      return new OperationResult(0, ExceptionalHaltReason.ILLEGAL_STATE_CHANGE);
    54→    }
    55→
    56→    final long cost = gasCalculator().logOperationGasCost(frame, dataLocation, numBytes, numTopics);
    57→    if (frame.getRemainingGas() < cost) {
    58→      return new OperationResult(cost, ExceptionalHaltReason.INSUFFICIENT_GAS);
    59→    }
    60→
    61→    final Address address = frame.getRecipientAddress();
    62→
    63→    final Bytes data = frame.readMemory(dataLocation, numBytes);
    64→
    65→    final ImmutableList.Builder<LogTopic> builder =
    66→        ImmutableList.builderWithExpectedSize(numTopics);
    67→    for (int i = 0; i < numTopics; i++) {
    68→      builder.add(LogTopic.create(leftPad(frame.popStackItem())));
    69→    }
    70→
    71→    frame.addLog(new Log(address, data, builder.build()));
    72→    return new OperationResult(cost, null);
    73→  }
    74→}
