    25→import org.hyperledger.besu.ethereum.core.Util;
    26→import org.hyperledger.besu.ethereum.core.Withdrawal;
    27→import org.hyperledger.besu.ethereum.core.encoding.EncodingContext;
    28→import org.hyperledger.besu.ethereum.core.encoding.TransactionEncoder;
    29→import org.hyperledger.besu.ethereum.core.encoding.WithdrawalEncoder;
    30→import org.hyperledger.besu.ethereum.core.encoding.receipt.TransactionReceiptEncoder;
    31→import org.hyperledger.besu.ethereum.core.encoding.receipt.TransactionReceiptEncodingConfiguration;
    32→import org.hyperledger.besu.ethereum.mainnet.block.access.list.BlockAccessList;
    33→import org.hyperledger.besu.ethereum.rlp.RLP;
    34→import org.hyperledger.besu.evm.log.LogsBloomFilter;
    35→
    36→import java.util.ArrayList;
    37→import java.util.List;
    38→
    39→import org.apache.tuweni.bytes.Bytes;
    40→
    41→/** A utility class for body validation tasks. */
    42→public final class BodyValidation {
    43→
    44→  private BodyValidation() {
    45→    // Utility Class
    46→  }
    47→
    48→  /**
    49→   * Generates the transaction root for a list of transactions
    50→   *
    51→   * @param transactions the transactions
    52→   * @return the transaction root
    53→   */
    54→  public static Hash transactionsRoot(final List<Transaction> transactions) {
    55→    final ArrayList<Bytes> bytesList = new ArrayList<>(transactions.size());
    56→    transactions.forEach(
    57→        t -> bytesList.add(TransactionEncoder.encodeOpaqueBytes(t, EncodingContext.BLOCK_BODY)));
    58→
    59→    return Util.getRootFromListOfBytes(bytesList);
    60→  }
    61→
    62→  /**
    63→   * Generates the withdrawals root for a list of withdrawals
    64→   *
    65→   * @param withdrawals the transactions
    66→   * @return the transaction root
    67→   */
    68→  public static Hash withdrawalsRoot(final List<Withdrawal> withdrawals) {
    69→    final ArrayList<Bytes> bytesList = new ArrayList<>(withdrawals.size());
    70→    withdrawals.forEach(w -> bytesList.add(WithdrawalEncoder.encodeOpaqueBytes(w)));
    71→
    72→    return Util.getRootFromListOfBytes(bytesList);
    73→  }
    74→
    75→  /**
    76→   * Generates the requests hash for a list of requests
    77→   *
    78→   * @param requests list of request (must be sorted by request type ascending)
    79→   * @return the requests hash
    80→   */
    81→  public static Hash requestsHash(final List<Request> requests) {
    82→    List<Bytes> requestHashes = new ArrayList<>();
    83→    requests.forEach(
    84→        request -> {
    85→          // empty requests are excluded from the hash
    86→          if (!request.getData().isEmpty()) {
    87→            requestHashes.add(sha256(request.getEncodedRequest()));
    88→          }
    89→        });
    90→
    91→    return Hash.wrap(sha256(Bytes.wrap(requestHashes)));
    92→  }
    93→
    94→  /**
    95→   * Generates the receipt root for a list of receipts
    96→   *
    97→   * @param receipts the receipts
    98→   * @return the receipt root
    99→   */
   100→  public static Hash receiptsRoot(final List<TransactionReceipt> receipts) {
   101→    final ArrayList<Bytes> bytesList = new ArrayList<>(receipts.size());
   102→    receipts.forEach(
   103→        receipt ->
   104→            bytesList.add(
   105→                RLP.encode(
   106→                    rlpOutput ->
   107→                        TransactionReceiptEncoder.writeTo(
   108→                            receipt,
   109→                            rlpOutput,
   110→                            TransactionReceiptEncodingConfiguration.TRIE_ROOT))));
   111→
   112→    return Util.getRootFromListOfBytes(bytesList);
   113→  }
   114→
   115→  /**
   116→   * Generates the ommers hash for a list of ommer block headers
   117→   *
   118→   * @param ommers the ommer block headers
   119→   * @return the ommers hash
   120→   */
   121→  public static Hash ommersHash(final List<BlockHeader> ommers) {
   122→    return Hash.wrap(keccak256(RLP.encode(out -> out.writeList(ommers, BlockHeader::writeTo))));
   123→  }
   124→
   125→  /**
   126→   * Generates the logs bloom filter for a list of transaction receipts
   127→   *
   128→   * @param receipts the transaction receipts
   129→   * @return the logs bloom filter
   130→   */
   131→  public static LogsBloomFilter logsBloom(final List<TransactionReceipt> receipts) {
   132→    final LogsBloomFilter.Builder filterBuilder = LogsBloomFilter.builder();
   133→
   134→    receipts.forEach(receipt -> filterBuilder.insertFilter(receipt.getBloomFilter()));
   135→
   136→    return filterBuilder.build();
   137→  }
   138→
   139→  /**
   140→   * Generates the block access list hash.
   141→   *
   142→   * @param bal the block access list
   143→   * @return the block access list hash
   144→   */
   145→  public static Hash balHash(final BlockAccessList bal) {
   146→    return Hash.wrap(sha256(RLP.encode(bal::writeTo)));
   147→  }
   148→}
