    26→
    27→import java.math.BigInteger;
    28→import java.util.Optional;
    29→import java.util.function.Supplier;
    30→
    31→import com.fasterxml.jackson.annotation.JsonCreator;
    32→import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
    33→import com.fasterxml.jackson.annotation.JsonProperty;
    34→import com.fasterxml.jackson.databind.annotation.JsonDeserialize;
    35→import com.google.common.base.Suppliers;
    36→import org.apache.tuweni.bytes.Bytes;
    37→
    38→// ignore `signer` field used in execution-spec-tests
    39→@JsonIgnoreProperties(ignoreUnknown = true)
    40→public class CodeDelegation implements org.hyperledger.besu.datatypes.CodeDelegation {
    41→  private static final Supplier<SignatureAlgorithm> SIGNATURE_ALGORITHM =
    42→      Suppliers.memoize(SignatureAlgorithmFactory::getInstance);
    43→
    44→  public static final Bytes MAGIC = Bytes.fromHexString("05");
    45→
    46→  private final BigInteger chainId;
    47→  private final Address address;
    48→  private final long nonce;
    49→  private final SECPSignature signature;
    50→  private final Supplier<Optional<Address>> authorizerSupplier =
    51→      Suppliers.memoize(this::computeAuthority);
    52→
    53→  /**
    54→   * An access list entry as defined in EIP-7702
    55→   *
    56→   * @param chainId can be either the current chain id or zero
    57→   * @param address the address from which the code will be set into the EOA account
    58→   * @param nonce the nonce after which this auth expires
    59→   * @param signature the signature of the EOA account which will be used to set the code
    60→   */
    61→  public CodeDelegation(
    62→      final BigInteger chainId,
    63→      final Address address,
    64→      final long nonce,
    65→      final SECPSignature signature) {
    66→    this.chainId = chainId;
    67→    this.address = address;
    68→    this.nonce = nonce;
    69→    this.signature = signature;
    70→  }
    71→
    72→  /**
    73→   * Create code delegation.
    74→   *
    75→   * @param chainId can be either the current chain id or zero
    76→   * @param address the address from which the code will be set into the EOA account
    77→   * @param nonce the nonce
    78→   * @param v the recovery id
    79→   * @param r the r value of the signature
    80→   * @param s the s value of the signature
    81→   * @return CodeDelegation
    82→   */
    83→  @JsonCreator
    84→  public static org.hyperledger.besu.datatypes.CodeDelegation createCodeDelegation(
    85→      @JsonProperty("chainId") @JsonDeserialize(using = ChainIdDeserializer.class)
    86→          final BigInteger chainId,
    87→      @JsonProperty("address") final Address address,
    88→      @JsonProperty("nonce") final String nonce,
    89→      @JsonProperty("v") final String v,
    90→      @JsonProperty("r") final String r,
    91→      @JsonProperty("s") final String s) {
    92→    return new CodeDelegation(
    93→        chainId,
    94→        address,
    95→        Bytes.fromHexStringLenient(nonce).toLong(),
    96→        SIGNATURE_ALGORITHM
    97→            .get()
    98→            .createCodeDelegationSignature(
    99→                Bytes.fromHexStringLenient(r).toUnsignedBigInteger(),
   100→                Bytes.fromHexStringLenient(s).toUnsignedBigInteger(),
   101→                Bytes.fromHexStringLenient(v).get(0)));
   102→  }
   103→
   104→  @JsonProperty("chainId")
   105→  @Override
   106→  public BigInteger chainId() {
   107→    return chainId;
   108→  }
   109→
   110→  @JsonProperty("address")
   111→  @Override
   112→  public Address address() {
   113→    return address;
   114→  }
   115→
   116→  @JsonProperty("signature")
   117→  @Override
   118→  public SECPSignature signature() {
   119→    return signature;
   120→  }
   121→
   122→  @Override
   123→  public Optional<Address> authorizer() {
   124→    // recId needs to be between either 0 or 1, otherwise the signature is invalid
   125→    // which means we can't recover the authorizer.
   126→    if (signature.getRecId() > 1 || signature.getRecId() < 0) {
   127→      return Optional.empty();
   128→    }
   129→
   130→    return authorizerSupplier.get();
   131→  }
   132→
   133→  @Override
   134→  public long nonce() {
   135→    return nonce;
   136→  }
   137→
   138→  @JsonProperty("v")
   139→  @Override
   140→  public byte v() {
   141→    return signature.getRecId();
   142→  }
   143→
   144→  @JsonProperty("r")
   145→  @Override
   146→  public BigInteger r() {
   147→    return signature.getR();
   148→  }
   149→
   150→  @JsonProperty("s")
   151→  @Override
   152→  public BigInteger s() {
   153→    return signature.getS();
   154→  }
   155→
   156→  private Optional<Address> computeAuthority() {
   157→    BytesValueRLPOutput rlpOutput = new BytesValueRLPOutput();
   158→    CodeDelegationTransactionEncoder.encodeSingleCodeDelegationWithoutSignature(this, rlpOutput);
   159→
   160→    final Hash hash = Hash.hash(Bytes.concatenate(MAGIC, rlpOutput.encoded()));
   161→
   162→    Optional<Address> authorityAddress;
   163→    try {
   164→      authorityAddress =
   165→          SIGNATURE_ALGORITHM
   166→              .get()
   167→              .recoverPublicKeyFromSignature(hash, signature)
   168→              .map(Address::extract);
   169→    } catch (final IllegalArgumentException e) {
   170→      authorityAddress = Optional.empty();
   171→    }
   172→
   173→    return authorityAddress;
   174→  }
   175→
   176→  /**
   177→   * Create a code delegation authorization with a builder.
   178→   *
   179→   * @return CodeDelegation.Builder
   180→   */
   181→  public static Builder builder() {
   182→    return new Builder();
   183→  }
   184→
   185→  /** Builder for CodeDelegation authorizations. */
   186→  public static class Builder {
   187→    private BigInteger chainId = BigInteger.ZERO;
   188→    private Address address;
   189→    private Long nonce;
   190→    private SECPSignature signature;
   191→
   192→    /** Create a new builder. */
   193→    protected Builder() {}
   194→
   195→    /**
   196→     * Set the optional chain id.
   197→     *
   198→     * @param chainId the chain id
   199→     * @return this builder
   200→     */
   201→    public Builder chainId(final BigInteger chainId) {
   202→      this.chainId = chainId;
   203→      return this;
   204→    }
   205→
   206→    /**
   207→     * Set the address of the authorized smart contract.
   208→     *
   209→     * @param address the address
   210→     * @return this builder
   211→     */
   212→    public Builder address(final Address address) {
   213→      this.address = address;
   214→      return this;
   215→    }
   216→
   217→    /**
   218→     * Set the nonce.
   219→     *
   220→     * @param nonce the nonce.
   221→     * @return this builder
   222→     */
   223→    public Builder nonce(final long nonce) {
   224→      this.nonce = nonce;
   225→      return this;
   226→    }
   227→
   228→    /**
   229→     * Set the signature of the authorizer account.
   230→     *
   231→     * @param signature the signature
   232→     * @return this builder
   233→     */
   234→    public Builder signature(final SECPSignature signature) {
   235→      this.signature = signature;
   236→      return this;
   237→    }
   238→
   239→    /**
   240→     * Sign the authorization with the given key pair and return the authorization.
   241→     *
   242→     * @param keyPair the key pair
   243→     * @return CodeDelegation
   244→     */
   245→    public org.hyperledger.besu.datatypes.CodeDelegation signAndBuild(final KeyPair keyPair) {
   246→      final BytesValueRLPOutput output = new BytesValueRLPOutput();
   247→      output.startList();
   248→      output.writeBigIntegerScalar(chainId);
   249→      output.writeBytes(address);
   250→      output.writeLongScalar(nonce);
   251→      output.endList();
   252→
   253→      signature(
   254→          SIGNATURE_ALGORITHM
   255→              .get()
   256→              .sign(Hash.hash(Bytes.concatenate(MAGIC, output.encoded())), keyPair));
   257→      return build();
   258→    }
   259→
   260→    /**
   261→     * Build the authorization.
   262→     *
   263→     * @return CodeDelegation
   264→     */
   265→    public org.hyperledger.besu.datatypes.CodeDelegation build() {
   266→      if (address == null) {
   267→        throw new IllegalStateException("Address must be set");
   268→      }
   269→
   270→      if (nonce == null) {
   271→        throw new IllegalStateException("Nonce must be set");
   272→      }
   273→
   274→      if (signature == null) {
   275→        throw new IllegalStateException("Signature must be set");
   276→      }
   277→
   278→      return new CodeDelegation(chainId, address, nonce, signature);
   279→    }
   280→  }
   281→
   282→  @Override
   283→  public String toString() {
   284→    return "CodeDelegation{"
   285→        + "chainId="
   286→        + chainId
   287→        + ", address="
   288→        + address
   289→        + ", nonce="
   290→        + nonce
   291→        + ", signature="
   292→        + signature
   293→        + ", authorizerSupplier="
   294→        + authorizerSupplier
   295→        + '}';
   296→  }
   297→}
