    38→// ignore `signer` field used in execution-spec-tests
    39→@JsonIgnoreProperties(ignoreUnknown = true)
    40→public class CodeDelegation implements org.hyperledger.besu.datatypes.CodeDelegation {
    41→  private static final Supplier<SignatureAlgorithm> SIGNATURE_ALGORITHM =
    42→      Suppliers.memoize(SignatureAlgorithmFactory::getInstance);
    43→
    44→  public static final Bytes MAGIC = Bytes.fromHexString("05");
    45→
    46→  private final BigInteger chainId;
    47→  private final Address address;
    48→  private final long nonce;
    49→  private final SECPSignature signature;
    50→  private final Supplier<Optional<Address>> authorizerSupplier =
    51→      Suppliers.memoize(this::computeAuthority);
    52→
    53→  /**
    54→   * An access list entry as defined in EIP-7702
    55→   *
    56→   * @param chainId can be either the current chain id or zero
    57→   * @param address the address from which the code will be set into the EOA account
    58→   * @param nonce the nonce after which this auth expires
    59→   * @param signature the signature of the EOA account which will be used to set the code
    60→   */
    61→  public CodeDelegation(
    62→      final BigInteger chainId,
    63→      final Address address,
    64→      final long nonce,
    65→      final SECPSignature signature) {
    66→    this.chainId = chainId;
    67→    this.address = address;
    68→    this.nonce = nonce;
    69→    this.signature = signature;
    70→  }
    71→
    72→  /**
    73→   * Create code delegation.
    74→   *
    75→   * @param chainId can be either the current chain id or zero
    76→   * @param address the address from which the code will be set into the EOA account
    77→   * @param nonce the nonce
    78→   * @param v the recovery id
    79→   * @param r the r value of the signature
    80→   * @param s the s value of the signature
    81→   * @return CodeDelegation
    82→   */
    83→  @JsonCreator
    84→  public static org.hyperledger.besu.datatypes.CodeDelegation createCodeDelegation(
    85→      @JsonProperty("chainId") @JsonDeserialize(using = ChainIdDeserializer.class)
    86→          final BigInteger chainId,
    87→      @JsonProperty("address") final Address address,
    88→      @JsonProperty("nonce") final String nonce,
    89→      @JsonProperty("v") final String v,
    90→      @JsonProperty("r") final String r,
    91→      @JsonProperty("s") final String s) {
    92→    return new CodeDelegation(
    93→        chainId,
    94→        address,
    95→        Bytes.fromHexStringLenient(nonce).toLong(),
    96→        SIGNATURE_ALGORITHM
    97→            .get()
    98→            .createCodeDelegationSignature(
    99→                Bytes.fromHexStringLenient(r).toUnsignedBigInteger(),
   100→                Bytes.fromHexStringLenient(s).toUnsignedBigInteger(),
   101→                Bytes.fromHexStringLenient(v).get(0)));
   102→  }
   103→
   104→  @JsonProperty("chainId")
