   108→  }
   109→
   110→  @JsonProperty("address")
   111→  @Override
   112→  public Address address() {
   113→    return address;
   114→  }
   115→
   116→  @JsonProperty("signature")
   117→  @Override
   118→  public SECPSignature signature() {
   119→    return signature;
   120→  }
   121→
   122→  @Override
   123→  public Optional<Address> authorizer() {
   124→    // recId needs to be between either 0 or 1, otherwise the signature is invalid
   125→    // which means we can't recover the authorizer.
   126→    if (signature.getRecId() > 1 || signature.getRecId() < 0) {
   127→      return Optional.empty();
   128→    }
   129→
   130→    return authorizerSupplier.get();
   131→  }
   132→
   133→  @Override
   134→  public long nonce() {
   135→    return nonce;
   136→  }
   137→
   138→  @JsonProperty("v")
   139→  @Override
   140→  public byte v() {
   141→    return signature.getRecId();
   142→  }
   143→
   144→  @JsonProperty("r")
   145→  @Override
   146→  public BigInteger r() {
   147→    return signature.getR();
   148→  }
   149→
   150→  @JsonProperty("s")
   151→  @Override
   152→  public BigInteger s() {
   153→    return signature.getS();
   154→  }
   155→
   156→  private Optional<Address> computeAuthority() {
   157→    BytesValueRLPOutput rlpOutput = new BytesValueRLPOutput();
   158→    CodeDelegationTransactionEncoder.encodeSingleCodeDelegationWithoutSignature(this, rlpOutput);
   159→
   160→    final Hash hash = Hash.hash(Bytes.concatenate(MAGIC, rlpOutput.encoded()));
   161→
   162→    Optional<Address> authorityAddress;
   163→    try {
   164→      authorityAddress =
   165→          SIGNATURE_ALGORITHM
   166→              .get()
   167→              .recoverPublicKeyFromSignature(hash, signature)
